import{_ as s,a,c as o,ac as t}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第一册：英语初阶 · 单元 6 复习与自测 · 第135–141课","description":"L121–L144 原创练习和答案解析。","frontmatter":{"title":"第一册：英语初阶 · 单元 6 复习与自测 · 第135–141课","description":"L121–L144 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-1/unit-06/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 单元 6 复习与自测","summary":"L121–L144 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 单元 6 复习与自测 · 第128–134课","link":"/life/english/new-concept/book-1/unit-06/review-part-02"},"next":{"text":"第一册：英语初阶 · 单元 6 复习与自测 · 第142–144课","link":"/life/english/new-concept/book-1/unit-06/review-part-04"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 单元 6 复习与自测 · 第128–134课","link":"/life/english/new-concept/book-1/unit-06/review-part-02"},"next":{"text":"第一册：英语初阶 · 单元 6 复习与自测 · 第142–144课","link":"/life/english/new-concept/book-1/unit-06/review-part-04"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-06/review-part-03.md","filePath":"life/english/new-concept/book-1/unit-06/review-part-03.md"}'),i={name:"life/english/new-concept/book-1/unit-06/review-part-03.md"};function n(l,e,r,h,d,p){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="第一册-英语初阶-·-单元-6-复习与自测-·-第135–141课" tabindex="-1">第一册：英语初阶 · 单元 6 复习与自测 · 第135–141课 <a class="header-anchor" href="#第一册-英语初阶-·-单元-6-复习与自测-·-第135–141课" aria-label="Permalink to &quot;第一册：英语初阶 · 单元 6 复习与自测 · 第135–141课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/unit-06/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/unit-06/overview">单元导读</a> · <a href="/life/english/new-concept/book-1/unit-06/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-1/unit-06/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-1/unit-06/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-135-·-would-与-had-done-的回移" tabindex="-1">Lesson 135 · would 与 had done 的回移 <a class="header-anchor" href="#lesson-135-·-would-与-had-done-的回移" aria-label="Permalink to &quot;Lesson 135 · would 与 had done 的回移 {#lesson-135-·-would-与-had-done-的回移}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> He said he would send the document the next day.</p><h3 id="练习-1-14" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-14" aria-label="Permalink to &quot;练习 1 {#练习-1-14}&quot;">​</a></h3><p>按回移转述：He said, &quot;I will send it.&quot;</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> He said he would send it.</p><p><strong>解析：</strong> 按本课规则判断：在常见的过去转述中，will 变 would，have/has done 变 had done。tomorrow 可根据转述时间改为 the next day，yesterday 改为 the day before。转述时间仍是同一天时不必机械替换。先明确谁在何时说话，再转换人称与时间，不能只做单词替换而让事件时间改变。</p></details><p><strong>表达迁移：</strong> 围绕“转述将来的安排和已经完成的动作”写两至三句，再读给同伴听。至少使用一次would 与 had done 的回移，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>He said he would send the document the next day. She told me she had finished the repairs.</p><p>Would send 是过去视角中的将来；the next day 表相对于原说话日的第二天，不能随转述日期任意漂移。 Told me 为主句，had finished 表相对于过去告诉我的时点已完成；the repairs 为从句宾语。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-135">回看本课</a></p><h2 id="lesson-136-·-would-与-had-done-的回移" tabindex="-1">Lesson 136 · would 与 had done 的回移 <a class="header-anchor" href="#lesson-136-·-would-与-had-done-的回移" aria-label="Permalink to &quot;Lesson 136 · would 与 had done 的回移 {#lesson-136-·-would-与-had-done-的回移}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> She told me she had finished the repairs.</p><h3 id="练习-1-15" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-15" aria-label="Permalink to &quot;练习 1 {#练习-1-15}&quot;">​</a></h3><p>按回移转述：She said, &quot;I have finished.&quot;</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She said she had finished.</p><p><strong>解析：</strong> 按本课规则判断：在常见的过去转述中，will 变 would，have/has done 变 had done。tomorrow 可根据转述时间改为 the next day，yesterday 改为 the day before。转述时间仍是同一天时不必机械替换。先明确谁在何时说话，再转换人称与时间，不能只做单词替换而让事件时间改变。</p></details><p><strong>表达迁移：</strong> 围绕“转述将来的安排和已经完成的动作”写两至三句，再读给同伴听。至少使用一次would 与 had done 的回移，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>She told me she had finished the repairs. He said he would send the document the next day.</p><p>Told me 为主句，had finished 表相对于过去告诉我的时点已完成；the repairs 为从句宾语。 Would send 是过去视角中的将来；the next day 表相对于原说话日的第二天，不能随转述日期任意漂移。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-136">回看本课</a></p><h2 id="lesson-137-·-真实条件句" tabindex="-1">Lesson 137 · 真实条件句 <a class="header-anchor" href="#lesson-137-·-真实条件句" aria-label="Permalink to &quot;Lesson 137 · 真实条件句 {#lesson-137-·-真实条件句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> If we finish early, we will take a walk.</p><h3 id="练习-1-16" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-16" aria-label="Permalink to &quot;练习 1 {#练习-1-16}&quot;">​</a></h3><p>填动词：If it ___ (rain), we will stay inside.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> rains</p><p><strong>解析：</strong> 按本课规则判断：表达未来可能实现的条件时，常用 if + 一般现在时，主句 will + 原形。if 从句不是已经发生，而是条件；主句也不是绝对保证，而是条件成立时的结果。从句放前面通常用逗号分隔，放后面通常不需要。不要因条件指未来就在普通 if 条件从句中机械加 will。</p></details><p><strong>表达迁移：</strong> 围绕“设想有可能发生的未来条件”写两至三句，再读给同伴听。至少使用一次真实条件句，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>If we finish early, we will take a walk. We will stay indoors if it rains tomorrow.</p><p>If we finish early 为条件，用一般现在时；we will take a walk 为条件成立后的结果，用 will 加原形。 主句 will stay 表结果，后置 if it rains tomorrow 表未来条件；rains 用现在时，不机械改 will rain。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-137">回看本课</a></p><h2 id="lesson-138-·-真实条件句" tabindex="-1">Lesson 138 · 真实条件句 <a class="header-anchor" href="#lesson-138-·-真实条件句" aria-label="Permalink to &quot;Lesson 138 · 真实条件句 {#lesson-138-·-真实条件句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> We will stay indoors if it rains tomorrow.</p><h3 id="练习-1-17" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-17" aria-label="Permalink to &quot;练习 1 {#练习-1-17}&quot;">​</a></h3><p>填主句：If we finish early, we ___ take a walk.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> will</p><p><strong>解析：</strong> 按本课规则判断：表达未来可能实现的条件时，常用 if + 一般现在时，主句 will + 原形。if 从句不是已经发生，而是条件；主句也不是绝对保证，而是条件成立时的结果。从句放前面通常用逗号分隔，放后面通常不需要。不要因条件指未来就在普通 if 条件从句中机械加 will。</p></details><p><strong>表达迁移：</strong> 围绕“设想有可能发生的未来条件”写两至三句，再读给同伴听。至少使用一次真实条件句，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We will stay indoors if it rains tomorrow. If we finish early, we will take a walk.</p><p>主句 will stay 表结果，后置 if it rains tomorrow 表未来条件；rains 用现在时，不机械改 will rain。 If we finish early 为条件，用一般现在时；we will take a walk 为条件成立后的结果，用 will 加原形。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-138">回看本课</a></p><h2 id="lesson-139-·-间接疑问句的陈述语序" tabindex="-1">Lesson 139 · 间接疑问句的陈述语序 <a class="header-anchor" href="#lesson-139-·-间接疑问句的陈述语序" aria-label="Permalink to &quot;Lesson 139 · 间接疑问句的陈述语序 {#lesson-139-·-间接疑问句的陈述语序}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> She wants to know whether the office is open.</p><h3 id="练习-1-18" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-18" aria-label="Permalink to &quot;练习 1 {#练习-1-18}&quot;">​</a></h3><p>排序：know / where / he / lives（I 开头）.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> I know where he lives.</p><p><strong>解析：</strong> 按本课规则判断：宾语从句中的疑问内容采用陈述语序：know where he lives，而非 know where does he live。一般疑问内容可用 if/whether 表“是否”；这里的 if 不表示条件。转述时去掉原问句帮助倒装的 do/does/did，但把所需时态保留在从句谓语。礼貌问句外层可以倒装，内层仍用陈述语序。</p></details><p><strong>表达迁移：</strong> 围绕“转述电话里提出的问题”写两至三句，再读给同伴听。至少使用一次间接疑问句的陈述语序，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>She wants to know whether the office is open. Could you tell me when the meeting starts?</p><p>Wants to know 是主句谓语结构；whether 表“是否”，从句 the office is open 采用陈述语序。 Could you tell me 是外层礼貌问句；内层 when the meeting starts 是间接疑问，不能再加 does 倒装。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-139">回看本课</a></p><h2 id="lesson-140-·-间接疑问句的陈述语序" tabindex="-1">Lesson 140 · 间接疑问句的陈述语序 <a class="header-anchor" href="#lesson-140-·-间接疑问句的陈述语序" aria-label="Permalink to &quot;Lesson 140 · 间接疑问句的陈述语序 {#lesson-140-·-间接疑问句的陈述语序}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Could you tell me when the meeting starts?</p><h3 id="练习-1-19" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-19" aria-label="Permalink to &quot;练习 1 {#练习-1-19}&quot;">​</a></h3><p>补“是否”：She asks ___ the office is open.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> if / whether</p><p><strong>解析：</strong> 按本课规则判断：宾语从句中的疑问内容采用陈述语序：know where he lives，而非 know where does he live。一般疑问内容可用 if/whether 表“是否”；这里的 if 不表示条件。转述时去掉原问句帮助倒装的 do/does/did，但把所需时态保留在从句谓语。礼貌问句外层可以倒装，内层仍用陈述语序。</p></details><p><strong>表达迁移：</strong> 围绕“转述电话里提出的问题”写两至三句，再读给同伴听。至少使用一次间接疑问句的陈述语序，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Could you tell me when the meeting starts? She wants to know whether the office is open.</p><p>Could you tell me 是外层礼貌问句；内层 when the meeting starts 是间接疑问，不能再加 does 倒装。 Wants to know 是主句谓语结构；whether 表“是否”，从句 the office is open 采用陈述语序。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-140">回看本课</a></p><h2 id="lesson-141-·-一般过去时被动语态" tabindex="-1">Lesson 141 · 一般过去时被动语态 <a class="header-anchor" href="#lesson-141-·-一般过去时被动语态" aria-label="Permalink to &quot;Lesson 141 · 一般过去时被动语态 {#lesson-141-·-一般过去时被动语态}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The guests were invited by email.</p><h3 id="练习-1-20" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-20" aria-label="Permalink to &quot;练习 1 {#练习-1-20}&quot;">​</a></h3><p>填 be：The guests ___ invited yesterday.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> were</p><p><strong>解析：</strong> 按本课规则判断：被动语态由 be + 过去分词构成，时态与主谓一致体现在 be 上。一般过去时用 was/were + 分词。只有及物动词及可接受的及物结构通常能转被动，happen 不可机械写 was happened。执行者不重要或未知时，可以省略引出执行者的 by 短语；如 by the host 中 the host 是执行者。by 也可表示方式，如本课 by email 表示通过电子邮件，不能把所有 by 短语都理解为执行者。</p></details><p><strong>表达迁移：</strong> 围绕“把注意力从执行者转向事件对象”写两至三句，再读给同伴听。至少使用一次一般过去时被动语态，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The guests were invited by email. This bridge was built fifty years ago.</p><p>The guests 为被邀请者，were invited 为过去被动；by email 表通过邮件这一方式，并非动作执行者。 This bridge 为动作承受者，was built 为单数过去被动；fifty years ago 为明确过去时间。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-141">回看本课</a></p>',60)])])}const w=s(i,[["render",n]]);export{u as __pageData,w as default};
